import json, collections
base = json.load(open('quiz.json', encoding='utf-8'))
for p,q,o,a,w in Q:
    base.append({"part":p,"q":q,"o":o,"a":a,"w":w})
json.dump(base, open('quiz_all.json','w',encoding='utf-8'), ensure_ascii=False)
c = collections.Counter(x['part'] for x in base)
print(len(base), dict(c))
